CREATE DATABASE IF NOT EXISTS absensi_karyawan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE absensi_karyawan;
CREATE TABLE karyawan (id INT AUTO_INCREMENT PRIMARY KEY,nip VARCHAR(30) UNIQUE NOT NULL,nama VARCHAR(100) NOT NULL,jabatan VARCHAR(100) NOT NULL,departemen VARCHAR(100) NOT NULL,no_hp VARCHAR(20),status ENUM('Aktif','Nonaktif') DEFAULT 'Aktif',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,karyawan_id INT NULL,nama VARCHAR(100) NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','karyawan') DEFAULT 'karyawan',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(karyawan_id) REFERENCES karyawan(id) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE absensi (id INT AUTO_INCREMENT PRIMARY KEY,karyawan_id INT NOT NULL,tanggal DATE NOT NULL,jam_masuk TIME NULL,jam_pulang TIME NULL,status ENUM('Hadir','Terlambat','Izin','Sakit','Alpha') DEFAULT 'Hadir',keterangan VARCHAR(255),latitude DECIMAL(10,7),longitude DECIMAL(10,7),foto VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unik_absensi_harian(karyawan_id,tanggal),FOREIGN KEY(karyawan_id) REFERENCES karyawan(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE pengajuan (id INT AUTO_INCREMENT PRIMARY KEY,karyawan_id INT NOT NULL,tanggal DATE NOT NULL,jenis ENUM('Izin','Sakit') NOT NULL,keterangan VARCHAR(255) NOT NULL,status ENUM('Menunggu','Disetujui','Ditolak') DEFAULT 'Menunggu',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(karyawan_id) REFERENCES karyawan(id) ON DELETE CASCADE ON UPDATE CASCADE);
